<script setup lang="ts">
import { onMounted, onBeforeUnmount, ref } from 'vue'
import { Upload, Download, Check, Pause } from '@lucide/vue'
import { readImportFile, downloadTemplate } from '../domain/importFile'
import * as api from '../domain/api'
import { priceFormat, unitLabels, type Category } from '../domain/catalog'
const props=defineProps<{categories:Category[];categoryId:number|null}>();const emit=defineEmits<{changed:[]}>()
const category=ref(props.categoryId??0);const job=ref<api.ImportJob|null>(null);const error=ref('');const busy=ref(false);const applying=ref(false);const pause=ref(false);const fileName=ref('');const input=ref<HTMLInputElement|null>(null)
async function select(file:File|undefined){if(!file)return;busy.value=true;error.value='';job.value=null;fileName.value=file.name;try{job.value=await api.previewImport(await readImportFile(file),category.value||null);sessionStorage.setItem('ukm-office-import',job.value.job)}catch(e){error.value=e instanceof Error?e.message:'Ошибка чтения файла'}finally{busy.value=false;if(input.value)input.value.value=''}}
async function resumeStatus(){const id=sessionStorage.getItem('ukm-office-import');if(!id)return;try{job.value=await api.getImport(id)}catch{sessionStorage.removeItem('ukm-office-import')}}onMounted(resumeStatus)
async function apply(){if(!job.value||applying.value)return;if(!confirm(`Сохранить изменения ${job.value.total} товаров на тестовом сайте? Новые значения справочников также будут добавлены. Выполненные операции записываются в историю.`))return;applying.value=true;pause.value=false;error.value='';try{while(job.value&&!job.value.complete&&!job.value.failed&&!pause.value){job.value=await api.applyImport(job.value.job,job.value.cursor)}emit('changed')}catch(e){error.value=e instanceof Error?e.message:'Ошибка загрузки. Обновите прогресс перед повтором.'}finally{applying.value=false}}
function beforeUnload(e:BeforeUnloadEvent){if(applying.value)e.preventDefault()}
window.addEventListener('beforeunload',beforeUnload);onBeforeUnmount(()=>{pause.value=true;window.removeEventListener('beforeunload',beforeUnload)})
async function refresh(){error.value='';try{if(job.value)job.value=await api.getImport(job.value.job)}catch(e){error.value=e instanceof Error?e.message:'Не удалось обновить'}}
</script>
<template><section><div class="page-heading"><div><h1>Импорт товаров</h1><p>Excel и CSV · сначала проверка, затем сохранение</p></div><button class="button" @click="downloadTemplate"><Download :size="17" />Скачать шаблон</button></div><div class="info-box"><p>До 200 товаров и 5 МБ в пачке. Обновление — по ID или артикулу; без них создаётся новый черновик. Пустые ячейки не меняют существующие данные. Для очистки укажите <strong>[очистить]</strong>. Новые значения характеристик будут перечислены в предпросмотре.</p></div><label class="category-picker">Раздел для новых товаров, если не указан в файле<select v-model="category" :disabled="busy||applying"><option :value="0">Не выбран</option><option v-for="c in categories" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><div class="upload-zone" @dragover.prevent @drop.prevent="!applying&&!busy&&select($event.dataTransfer?.files[0])"><Upload :size="28" /><p>{{ busy?'Проверяем файл…':fileName||'Перетащите файл .xlsx или .csv' }}</p><button class="button" :disabled="busy||applying" @click="input?.click()">Выбрать файл</button><input ref="input" type="file" accept=".xlsx,.csv" class="sr-only" aria-label="Файл импорта" :disabled="busy||applying" @change="select(($event.target as HTMLInputElement).files?.[0])" /></div><p v-if="error" class="error-notice" role="alert">{{ error }}</p><template v-if="job"><div v-if="job.errors.length" class="error-notice" role="alert"><strong>Ничего не загружено. Исправьте ошибки в файле:</strong><p v-for="e in job.errors" :key="e.row">Строка {{ e.row }}: {{ e.message }}</p></div><p v-if="job.failed" class="error-notice" role="alert">Остановлено на строке {{ job.failed.row }}: {{ job.failed.message }}. Сохранено {{ job.cursor }} товаров; их можно отменить через историю.</p><div class="page-heading"><div><h2>{{ job.complete?'Импорт завершён':'Предпросмотр изменений' }}</h2><p>Проверено: {{ job.total }} · Сохранено: {{ job.cursor }} / {{ job.total }}</p></div><span v-if="job.complete" class="badge neutral"><Check :size="13" />Готово</span></div><div class="table-scroll"><table class="products-table"><thead><tr><th>Строка</th><th>Товар</th><th>Действие</th><th>Цена</th><th>Новые значения</th></tr></thead><tbody><tr v-for="p in job.preview" :key="p.row"><td>{{ p.row }}</td><td>{{ p.name }}<small class="muted"> {{ p.id?'ID '+p.id:'новый' }}</small></td><td>{{ p.operation==='create'?'Создание':'Обновление' }}<small class="muted"> · {{ p.changes.length }} полей</small></td><td>{{ p.price===null?'Узнать цену':priceFormat.format(p.price)+' ₽/'+(unitLabels[p.unit]??p.unit) }}</td><td>{{ p.newTerms.map(t=>t.name).join(', ')||'—' }}</td></tr></tbody></table></div><p class="muted section-gap">Обрабатываем по пять строк. Можно остановиться между порциями. Вся пачка не откатывается автоматически при ошибке; каждое выполненное изменение доступно в истории.</p><div class="modal-actions"><button class="button" :disabled="applying" @click="refresh">Обновить прогресс</button><button v-if="applying" class="button" @click="pause=true"><Pause :size="16" />Остановить после текущей порции</button><button v-else-if="!job.complete" class="button primary" :disabled="job.errors.length>0||!!job.failed||job.total===0" @click="apply">{{ job.cursor?'Продолжить импорт':'Подтвердить и сохранить на тесте' }}</button></div></template><details class="section-gap"><summary>Какие колонки поддерживаются</summary><p class="muted">ID, Артикул, Название, Категория (ID или однозначное имя), Цена, Единица (м, кг, т, шт., м²), Статус (черновик/опубликован), Описание, Краткое описание. Для характеристик — «Характеристика:Название». Несколько значений разделяйте символом |. При совпадающих названиях справочников используйте «Характеристика:pa_ключ».</p></details></section></template>
